<template><div class="mx-auto max-w-lg rounded bg-white p-6 shadow"><h1 class="mb-6 text-2xl font-bold">회원정보 수정</h1><form v-if="form" @submit.prevent="save" class="space-y-3"><input v-model="form.name" class="w-full rounded border p-3"><input v-model="form.tel" class="w-full rounded border p-3"><input v-model="form.email" class="w-full rounded border p-3"><input v-model="form.password" type="password" placeholder="새 비밀번호(선택)" class="w-full rounded border p-3"><button class="rounded bg-slate-900 px-5 py-2 text-white">저장</button></form></div></template>
<script setup>import{onMounted,reactive}from'vue';import{useRouter}from'vue-router';import{memberApi}from'../api/memberApi';const router=useRouter(),form=reactive({name:'',tel:'',email:'',password:''});onMounted(async()=>Object.assign(form,(await memberApi.me()).data));async function save(){await memberApi.update(form);router.push('/mypage')}</script>